function validate([left, right]) {
  if (!Number.isInteger(left) || !Number.isInteger(right)) return 'left and right are integers.';
  if (left < 1 || right > 1000000) return 'left and right are between 1 and 10^6.';
  if (left > right) return 'left must not exceed right.';
  return null;
}

