function closestPrimes(left, right) {
  const composite = new Uint8Array(right + 1);
  composite[0] = 1;
  composite[1] = 1;
  for (let p = 2; p * p <= right; p++) {
    if (!composite[p]) {
      for (let multiple = p * p; multiple <= right; multiple += p) {
        composite[multiple] = 1;
      }
    }
  }
  let answer = [-1, -1];
  let previous = -1;
  for (let num = left; num <= right; num++) {
    if (composite[num]) {
      continue;
    }
    if (previous !== -1 && (answer[0] === -1 || num - previous < answer[1] - answer[0])) {
      answer = [previous, num];
    }
    previous = num;
  }
  return answer;
}

