function closestPrimes(left, right) {
  // Collect the primes by trial division, then compare every pair.
  const isPrime = (x) => {
    if (x < 2) return false;
    for (let d = 2; d * d <= x; d++) if (x % d === 0) return false;
    return true;
  };
  const primes = [];
  for (let x = left; x <= right; x++) if (isPrime(x)) primes.push(x);
  let best = [-1, -1];
  for (let i = 0; i < primes.length; i++)
    for (let j = i + 1; j < primes.length; j++) {
      const gap = primes[j] - primes[i];
      if (best[0] === -1 || gap < best[1] - best[0] || (gap === best[1] - best[0] && primes[i] < best[0])) best = [primes[i], primes[j]];
    }
  return best;
}

