function generate(rand, size) {
  const limit = 1000000;
  if (size === 'large') {
    const style = Math.floor(rand() * 3);
    if (style === 0) return [1 + Math.floor(rand() * 1000), limit - Math.floor(rand() * 1000)];
    const left = 1 + Math.floor(rand() * limit);
    if (style === 1) return [left, left + Math.floor(rand() * (limit - left + 1))];
    return [1 + Math.floor(rand() * 200000), 800000 + Math.floor(rand() * 200001)];
  }
  const style = Math.floor(rand() * 3);
  if (style === 0) {
    const left = 1 + Math.floor(rand() * 40);
    return [left, Math.min(limit, left + Math.floor(rand() * 30))];
  }
  if (style === 1) {
    const left = 1 + Math.floor(rand() * 2000);
    return [left, left + Math.floor(rand() * 60)];
  }
  const left = limit - Math.floor(rand() * 300);
  return [left, Math.min(limit, left + Math.floor(rand() * 200))];
}
